<?php
require_once __DIR__.'/../app/bootstrap.php';require_once __DIR__.'/../app/appointments.php';$adminUser=require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();try{change_appointment_status((int)input_text($_POST,'id'),input_text($_POST,'status'),(int)input_text($_POST,'version'),$adminUser);flash('The demo request status has been updated.');}catch(DomainException $error){flash($error->getMessage(),'error');}redirect('admin/appointments.php');}
$status=input_text($_GET,'status','all');$allowedStatuses=['requested','confirmed','completed','cancelled'];$condition=in_array($status,$allowedStatuses,true)?' WHERE status=?':'';$params=$condition?[$status]:[];
$page=max(1,(int)input_text($_GET,'page','1'));$total=(int)query('SELECT COUNT(*) FROM appointment_requests'.$condition,$params)->fetchColumn();$pages=max(1,(int)ceil($total/15));$page=min($page,$pages);
$requests=query('SELECT *,TIME_FORMAT(preferred_time,"%H:%i") AS time_label FROM appointment_requests'.$condition.' ORDER BY id DESC LIMIT 15 OFFSET '.(($page-1)*15),$params)->fetchAll();
$pageTitle='Appointments | Wellnest Workspace';$adminSection='appointments';$adminPageLabel='Appointments';require __DIR__.'/../components/admin_header.php';
?>
<div class="admin-page-heading"><div><span class="admin-eyebrow">EVERY REQUEST IS A FIRST STEP</span><h1>Visit requests<span>.</span></h1><p>Review preferred visits and keep their demo status up to date.</p></div><span class="admin-today"><?=icon('calendar')?> GMT+7</span></div><section class="admin-panel"><div class="services-toolbar"><div class="request-tabs"><?php foreach(array_merge(['all'],$allowedStatuses) as $filter): ?><a class="<?=$filter===$status?'active':''?>" href="<?=e(base_url('admin/appointments.php?status='.$filter))?>"><?=e(ucfirst($filter))?></a><?php endforeach; ?></div><span class="results-label"><?=$total?> requests</span></div><div class="admin-table-wrap"><table class="admin-table appointments-table"><thead><tr><th>Patient & reference</th><th>Service</th><th>Preferred visit</th><th>Status</th><th>Next step</th></tr></thead><tbody><?php foreach($requests as $request): ?><tr><td><strong><?=e($request['full_name'])?></strong><small><?=e($request['email'])?></small><small class="request-reference"><?=e($request['reference'])?></small></td><td><strong><?=e($request['service_name'])?></strong><small><?=money((int)$request['quoted_price'])?></small></td><td><strong><?=e(date('d M Y',strtotime($request['preferred_date'])))?></strong><small><?=e($request['time_label'])?> · GMT+7</small></td><td><span class="status-badge status-<?=e($request['status'])?>"><?=e(ucfirst($request['status']))?></span></td><td><?php $next=['requested'=>['confirmed'=>'Confirm demo','cancelled'=>'Cancel'],'confirmed'=>['completed'=>'Complete demo','cancelled'=>'Cancel']][$request['status']]??[];if($next): ?><form method="post" class="status-form"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($request['id'])?>"><input type="hidden" name="version" value="<?=e($request['version'])?>"><label class="visually-hidden" for="next-status-<?=e($request['id'])?>">Next status for <?=e($request['reference'])?></label><select id="next-status-<?=e($request['id'])?>" name="status" class="form-select"><?php foreach($next as $value=>$label): ?><option value="<?=e($value)?>"><?=e($label)?></option><?php endforeach; ?></select><button type="submit" class="table-action" aria-label="Update <?=e($request['reference'])?>"><?=icon('check')?></button></form><?php else: ?><span class="terminal-status"><?=icon('check')?> Closed</span><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$requests): ?><tr><td colspan="5" class="table-empty">No requests in this view.</td></tr><?php endif; ?></tbody></table></div><div class="table-pagination"><span><?=$total?> total requests</span><nav aria-label="Appointment pages"><?php for($n=1;$n<=$pages;$n++): ?><a class="<?=$n===$page?'active':''?>" href="<?=e(base_url('admin/appointments.php?'.http_build_query(['status'=>$status,'page'=>$n])))?>" <?=$n===$page?'aria-current="page"':''?>><?=$n?></a><?php endfor; ?></nav></div></section><p class="admin-bottom-note"><?=icon('shield')?> Statuses apply to this student demo only. No emails are sent and no clinical appointments are booked.</p>
